package protocol

import "strings"

// AllDirectMessages is the history/observation target for the human DM audit
// view. It excludes channel traffic, including channel mentions.
const AllDirectMessages = "@*"

const (
	ReplyTag  = "+airc/reply-to"
	ThreadTag = "+airc/thread"
)

// ValidMessageID accepts the canonical IDs generated by aircd: 32 lowercase
// hexadecimal characters. Paste, handoff, decision and account IDs have the
// same shape. It is the test for an ID the daemon emitted; an argument may
// abbreviate one (ValidIDArgument).
func ValidMessageID(id string) bool {
	return len(id) == 32 && lowerHex(id)
}

// MinIDPrefix is the shortest abbreviation of an ID an argument may give.
const MinIDPrefix = 8

// ValidIDArgument accepts what a command's ID argument may be: a full ID,
// or its first MinIDPrefix or more characters, which the daemon resolves
// among the IDs it retains and refuses when more than one matches.
func ValidIDArgument(arg string) bool {
	return len(arg) >= MinIDPrefix && len(arg) <= 32 && lowerHex(arg)
}

func lowerHex(s string) bool {
	for _, c := range s {
		if !(c >= '0' && c <= '9' || c >= 'a' && c <= 'f') {
			return false
		}
	}
	return true
}

// ConversationTarget recognizes history/observation selectors. A thread
// includes its root and descendants; replies selects only immediate replies.
// The ID may be abbreviated (ValidIDArgument); the daemon resolves it.
func ConversationTarget(target string) (id string, replies bool, ok bool) {
	if id, found := strings.CutPrefix(target, "thread:"); found {
		return id, false, ValidIDArgument(id)
	}
	id, found := strings.CutPrefix(target, "replies:")
	return id, true, found && ValidIDArgument(id)
}
